def sha(b):
    return hashlib.sha256(b).hexdigest()

def add(origin, path, raw, kind, value=None):
    identity = sha(raw)
    record = json.loads((SPOOL/(identity+'.json')).read_text()) if (SPOOL/(identity+'.json')).exists() else {'id': identity, 'original_bytes': len(raw), 'kind': kind, 'origins': []}
    location = {'container': origin, 'path': path}
    if location not in record['origins']:
        record['origins'].append(location)
    if 'text' not in record and 'data' not in record:
        if value is None:
            record['text'] = raw.decode()
        else:
            record['data'] = value
    (SPOOL/(identity+'.json')).write_text(json.dumps(record,ensure_ascii=False,separators=(',',':')))
    records[identity] = {k:v for k,v in record.items() if k not in {'text','data'}}
    return identity

def compact(value, key=''):
    if isinstance(value, dict):
        result = {}
        for k, v in value.items():
            if k in {'public_states', 'ready', 'receipts', 'console', 'log', 'logs', 'events', 'raw_graphs', 'rawGraphs', 'rawFrames', 'frameSamples', 'completed_render_ends_ns'}:
                result[k] = {'compacted': True, 'count': len(v) if isinstance(v, (list,dict,str)) else None, 'sha256': sha(json.dumps(v, sort_keys=True, separators=(',', ':')).encode())}
            else:
                result[k] = compact(v, k)
        return result
    if isinstance(value,str) and len(value)>32768:
        return {'compacted_text':True,'bytes':len(value.encode()),'sha256':sha(value.encode()),'start':value[:2000],'end':value[-2000:]}
    if isinstance(value, list):
        if len(value)>64 and not all(isinstance(v,(int,float)) for v in value) and key not in {'runs','baselines','cells','windows','cases','scenarios','controls','targets','measurements','comparisons','observations'}:
            statuses=collections.Counter(str(v.get('status',v.get('outcome','unknown'))) for v in value if isinstance(v,dict))
            return {'compacted_record_series':True,'count':len(value),'statuses':dict(statuses),'sha256':sha(json.dumps(value,sort_keys=True,separators=(',',':')).encode())}
        if len(value)>64 and all(isinstance(v,(int,float)) and not isinstance(v,bool) for v in value):
            nums = [v for v in value if math.isfinite(v)]
            order = sorted(nums)
            return {'compacted_numeric_series': True, 'count': len(value), 'finite_count': len(nums), 'mean': statistics.fmean(nums) if nums else None, 'sample_sd': statistics.stdev(nums) if len(nums)>1 else None, 'min': min(nums) if nums else None, 'max': max(nums) if nums else None, 'p50_nearest_rank': order[max(0, math.ceil(len(order)*.5)-1)] if nums else None, 'p95_nearest_rank': order[max(0, math.ceil(len(order)*.95)-1)] if nums else None, 'p99_nearest_rank': order[max(0, math.ceil(len(order)*.99)-1)] if nums else None, 'first': value[0], 'last': value[-1], 'sha256': sha(json.dumps(value,separators=(',',':')).encode())}
        return [compact(v, key) for v in value]
    return value

archive = Path('/home/philip/.local/share/shaderlod-next/evidence/history/earlier-document-archive/docs-and-agent-setup.tar.gz')
archive_texts = {}
with tarfile.open(archive) as t:
    for member in t.getmembers():
        if not member.isfile():
