        raw = t.extractfile(member).read()
        text = raw.decode()
        archive_texts[member.name] = text
        path = member.name
        if '.history.' in path or '/goals/' in path or '/handoffs/' in path:
            coverage.append({'origin': 'earlier-documents', 'path': path, 'sha256': sha(raw), 'disposition': 'historical-ledger-extraction'})
            continue
        if not path.startswith('docs/') or Path(path).name.upper() in {'AGENT_OPERATIONS.MD','README.MD','STATUS.MD','EXPERIMENTS.MD','PC_TESTING.MD','HEADLESS.MD','WINDOWS_BENCHMARK.MD'}:
            coverage.append({'origin':'earlier-documents','path':path,'sha256':sha(raw),'disposition':'obsolete-working-instructions'})
            continue
        if path.endswith('.json'):
            identity = add('earlier-documents',path,raw,'structured-historical-report',json.loads(text))
        else:
            identity = add('earlier-documents',path,raw,'historical-report')
        coverage.append({'origin':'earlier-documents','path':path,'sha256':sha(raw),'disposition':'retained-report','record':identity})

corpus = {line.strip() for path,text in archive_texts.items() if '.history.' not in path and '/goals/' not in path and '/handoffs/' not in path for line in text.splitlines()}
ledger = {}
for path, text in archive_texts.items():
    if '.history.' not in path and '/goals/' not in path and '/handoffs/' not in path:
        continue
    clean = re.sub(r'<!--.*?-->', '', text, flags=re.S)
    heading = ''
    for line in clean.splitlines():
        if line.startswith('#'):
            heading = line.strip()
        line = line.strip()
        if len(line) < 35 or len(line)>3000 or line in corpus:
