        if not re.search(r'\d[\d.,−–+-]*\s*(?:%|ms\b|fps\b|MiB\b|GiB\b)|\|.*\d.*\|', line, re.I):
            continue
        identity = sha(line.encode())
        entry=ledger.setdefault(identity,{'text':line,'context':heading,'origins':[]})
        if len(entry['origins'])<3:
            entry['origins'].append(path)
raw=json.dumps(list(ledger.values()),sort_keys=True).encode()
add('earlier-documents','deduplicated-ledger-measurement-excerpts',raw,'historical-reported-excerpts',list(ledger.values()))
print('Earlier reports',len(records),'ledger excerpts',len(ledger),flush=True)

manifest=json.loads(Path('/home/philip/.local/share/shaderlod-next/evidence/history/snapshot-manifest.json').read_text())['files']
excluded = {'client','frozen','source','src','dependencies','chart-env','input-transfer','setup-archives','build','classes','libraries','assets','.gradle','.git','world-restore','worlds','canonical-pbr','runtime','profiles'}
top_exclude = re.compile(r'(?:fixture-|storage|inventory|cleanup|transfer|source-manifest|verification|\.request\.|setup|preflight|preservation|archive-retention|source-sync|git-status|queue|jobs-|desktop|wifi|known_hosts|bootstrap|host-state)',re.I)
summary_names={'summary.json','result.json','runtime-result.json','clock-summary.json','live-result.json','comparison.json','evaluation.json','final-interpretation.json','quality-analysis.json','quality-summary.json'}
selected=[]
