def batch_write(prefix, entries):
    chunks=[]; current=[]; size=0
    for entry in entries:
        data=json.dumps(entry,ensure_ascii=False,separators=(',',':')).encode()
        if len(data)>1800000:
            if 'data' in entry and isinstance(entry['data'],dict):
                sub=[]
                for key,val in entry['data'].items():
                    raw=json.dumps(val,ensure_ascii=False,separators=(',',':')).encode()
                    if len(raw)>1500000 and isinstance(val,list):
                        for i in range(0,len(val),20):
                            sub.append({'id':entry['id']+':'+key+':'+str(i),'part_of':entry['id'],'key':key,'start':i,'data':val[i:i+20]})
                    else:
                        sub.append({'id':entry['id']+':'+key,'part_of':entry['id'],'key':key,'data':val})
                entry={'id':entry['id'],'kind':entry['kind'],'original_bytes':entry['original_bytes'],'origins':entry['origins'],'parts':[e['id'] for e in sub]}
                data=json.dumps(entry,separators=(',',':')).encode()
                entries.extend(sub)
            elif isinstance(entry.get('data'),list):
                val=entry['data'];sub=[]
                for i in range(0,len(val),20):
                    sub.append({'id':entry['id']+':'+str(i),'part_of':entry['id'],'start':i,'data':val[i:i+20]})
                entry={k:v for k,v in entry.items() if k!='data'}|{'parts':[e['id'] for e in sub]}
                entries.extend(sub);data=json.dumps(entry,separators=(',',':')).encode()
            else:
                raise ValueError('oversized '+entry['id'])
        if size+len(data)>1250000 and current:
            chunks.append(current);current=[];size=0
        current.append(entry);size+=len(data)
    if current:chunks.append(current)
    locations={}
    for i,chunk in enumerate(chunks):
        name=f'{prefix}-{i+1:02}.json'
        payload=json.dumps({'schema':'shaderlod-compact-historical-records-v1','records':chunk},ensure_ascii=False,separators=(',',':')).encode()+b'\n'
        assert len(payload)<2*1024*1024,(name,len(payload))
        (OUT/name).write_bytes(payload)
        for record in chunk:
            locations[record['id']]=name
    return locations

