groups=collections.defaultdict(list)
condition_sets={}

def encoded(value):
    return json.dumps(value,ensure_ascii=False,separators=(',',':')).encode()

def diagnostic(value, depth=0):
    if not isinstance(value,(dict,list)):
        return value if not isinstance(value,str) or len(value)<1000 else {'text_bytes':len(value.encode()),'sha256':hashlib.sha256(value.encode()).hexdigest()}
    if isinstance(value,list):
        counts=collections.Counter(str(v.get('status',v.get('outcome','unknown'))) for v in value if isinstance(v,dict))
        return {'omitted_diagnostic_entries':len(value),'reported_status_counts':dict(counts)}
    if depth>=1 and len(value)>40:
        return {'omitted_diagnostic_dictionary_entries':len(value),'retained_status_fields':{k:v for k,v in value.items() if k.lower() in {'status','valid','failure','reason','scope','count','eligible','active','enabled','availability','coverage'}}}
    if depth>=1:
        return {k:v for k,v in value.items() if not isinstance(v,(dict,list)) and (not isinstance(v,str) or len(v)<1000)} | {'omitted_nested_fields':[k for k,v in value.items() if isinstance(v,(dict,list))]}
    return {k:diagnostic(v,depth+1) for k,v in value.items()}

def project(value,key=''):
    if isinstance(value,dict):
        result={}
        for k,v in value.items():
            if k in {'effectiveOptions','native_option_snapshot','featureProfile'} and isinstance(v,(dict,list)) and len(encoded(v))>1500:
                identity=hashlib.sha256(encoded(v)).hexdigest()
                condition_sets.setdefault(identity,{'id':identity,'original_bytes':len(encoded(v)),'kind':'tested-options','origins':[{'container':'extracted-condition-map','path':k}],'data':v})
                result[k]={'retained_options_id':identity}
            elif isinstance(v,(dict,list)) and re.search(r'observations|activation|diagnostic|cpu_work|work_images|assessment|witness|native_return|private_bindings',k,re.I) and len(encoded(v))>5000:
                result[k]={'projection':'diagnostic scalar/status summary; no draw trace retained','data':diagnostic(v)}
            elif k in {'draws','drawCalls','frames','samples','frameSamples','programs','linkedPrograms','snapshots','sources','source_inventory','source_files','build_files','class_files','fileHashes'} and isinstance(v,(dict,list)) and len(encoded(v))>5000:
                result[k]={'projection':'discarded repeated implementation/trace detail','entries':len(v),'sha256':hashlib.sha256(encoded(v)).hexdigest()}
            else:
                result[k]=project(v,k)
        return result
    if isinstance(value,list):
        return [project(v,key) for v in value]
    return value

def topic(record):
    origin=record['origins'][0]
    path=origin['path'].lower()
    if origin['container']=='old-5080-runs.tar.gz':
        return 'earlier-rtx-controls'
    if record['kind']=='historical-reported-excerpts':
        return 'earlier-measurement-excerpts'
    if record['kind']=='historical-authored-source':
        return 'authored-source'
    if '/experiments/' in path:
        return path.split('/experiments/',1)[1].split('/')[0]
    if '/logs/' in path:
        return 'runtime-history'
    if record['kind']=='retired-source-reference':
