def write_group(topic,items):
    chunks=[]
    current=[];size=0
    for record in items:
        if len(encoded(record))>1250000 and isinstance(record.get('data'),dict):
            data=record.pop('data');parts=[]
            for key,value in data.items():
                if len(encoded(value))>900000 and isinstance(value,list):
                    for start in range(0,len(value),max(1,min(10,len(value)//2))):
                        parts.append({'id':record['id']+':'+key+':'+str(start),'part_of':record['id'],'key':key,'start':start,'data':value[start:start+max(1,min(10,len(value)//2))]})
                else:
                    parts.append({'id':record['id']+':'+key,'part_of':record['id'],'key':key,'data':value})
            record['parts']=[p['id'] for p in parts]
            items.extend(parts)
        elif len(encoded(record))>1250000 and isinstance(record.get('data'),list):
            data=record.pop('data');parts=[]
            for start in range(0,len(data),max(1,min(10,len(data)//2))):
                parts.append({'id':record['id']+':'+str(start),'part_of':record['id'],'start':start,'data':data[0] if len(data)==1 else data[start:start+max(1,min(10,len(data)//2))],'single_list_element':len(data)==1})
            record['parts']=[p['id'] for p in parts];items.extend(parts)
        if isinstance(record.get('data'),list) and len(record['data'])==1 and len(encoded(record['data']))>1250000:
            record['data']=record['data'][0]
            record['single_list_element']=True
        payload=encoded(record)
        assert len(payload)<2*1024*1024,(topic,record['id'],len(payload))
        if current and size+len(payload)>1250000:
            chunks.append(current);current=[];size=0
        current.append(record);size+=len(payload)
    if current:
        chunks.append(current)
    for index,chunk in enumerate(chunks):
        name=f'{topic}-{index+1:02}.json'
        raw=encoded({'schema':'shaderlod-compact-historical-records-v1','records':chunk})+b'\n'
        assert len(raw)<2*1024*1024,(name,len(raw))
        (out/name).write_bytes(raw)
        file_manifest.append({'file':name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()})
        for record in chunk:
            if 'origins' in record:
                catalog.append({'id':record['id'],'file':name,'kind':record['kind'],'topic':topic,'origins':record['origins']})

